import logo from './logo.svg';
import './App.css';
import Login from './Page/Login.js';

function AdminPA(props) {
    return null;
}

function PredPA(props) {
    return null;
}

function UserPA(props) {
    return null;
}

function App() {
    const [authInfo, setAuthInfo] = useState({
        isLoggedIn: false,
        role: null
    });
    const [showLoginModal, setShowLoginModal] = useState(false);

    const handleLoginClick = () => {
        setShowLoginModal(true);
    };

    const handleSuccessfulLogin = (role) => {
        setAuthInfo({
            isLoggedIn: true,
            role: role
        });
        setShowLoginModal(false);
    };

    const handleCloseModal = () => {
        setShowLoginModal(false);
    };

    const handleLogout = () => {
        setAuthInfo({
            isLoggedIn: false,
            role: null
        });
    };

    return (
        <div className="app-container">
            {!authInfo.isLoggedIn ? (
                <header className="header">
                    <div className="logo-container">
                        <img src={logo} alt="Логотип ТНС Энерго" className="logo" />
                    </div>
                    <button
                        className="login-btn"
                        onClick={handleLoginClick}
                        aria-label="Вход"
                    >
                        <FaSignInAlt size={18} />
                        <span className="login-text">Войти</span>
                    </button>
                </header>
            ) : authInfo.role === 'admin' ? (
                <AdminPA onLogout={handleLogout} />
            ) : authInfo.role === 'pred' ? (
                <PredPA onLogout={handleLogout} />
            ) : (
                <UserPA onLogout={handleLogout} />
            )}

            {!authInfo.isLoggedIn && !showLoginModal && (
                <div className="welcome-message">
                    <h2>Добро пожаловать в систему ТНС Энерго</h2>
                    <p>Пожалуйста, войдите в систему для доступа к функциям</p>
                </div>
            )}

            {showLoginModal && (
                <Login
                    onLogin={handleSuccessfulLogin}
                    onClose={handleCloseModal}
                />
            )}
        </div>
    );
}

export default App;
